import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long k = scanner.nextLong();
        scanner.close();

        // Find the maximum m where m! <= k
        int m = 0;
        long fact = 1;
        while (fact < k) {
            m++;
            if (m > 20) break; // Prevent overflow, since 20! is way larger than 1e9
            fact *= m;
        }

        // Check if m exceeds n, meaning the permutation doesn't exist
        if (m > n) {
            System.out.println(-1);
            return;
        }

        // Generate the permutation for the last m elements
        List<Long> perm = new ArrayList<>();
        for (long i = n - m + 1; i <= n; i++) {
            perm.add(i);
        }

        // Convert k to 0-based index
        long currentK = k - 1;
        List<Long> result = new ArrayList<>();
        int size = perm.size();
        for (int i = 0; i < size; i++) {
            long f = factorial(size - i - 1);
            int index = (int) (currentK / f);
            result.add(perm.get(index));
            perm.remove(index);
            currentK %= f;
        }

        // Generate all lucky numbers up to n
        List<Long> luckyNumbers = generateLuckyNumbers(n);

        // Create a set for quick lookup
        java.util.HashSet<Long> luckySet = new java.util.HashSet<>(luckyNumbers);

        // Check positions from 1 to n
        int count = 0;
        for (long i = 1; i <= n; i++) {
            if (luckySet.contains(i)) {
                long value;
                if (i <= n - m) {
                    value = i;
                } else {
                    int posInResult = (int) (i - (n - m) - 1);
                    value = result.get(posInResult);
                }
                if (luckySet.contains(value)) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }

    private static long factorial(int n) {
        long res = 1;
        for (int i = 2; i <= n; i++) {
            res *= i;
        }
        return res;
    }

    private static List<Long> generateLuckyNumbers(long max) {
        List<Long> lucky = new ArrayList<>();
        generateLuckyNumbersHelper(0, max, lucky);
        return lucky;
    }

    private static void generateLuckyNumbersHelper(long current, long max, List<Long> lucky) {
        if (current > max) {
            return;
        }
        if (current != 0) {
            lucky.add(current);
        }
        generateLuckyNumbersHelper(current * 10 + 4, max, lucky);
        generateLuckyNumbersHelper(current * 10 + 7, max, lucky);
    }
}
